pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 plays) public {
        // Bound to a reasonable number of plays to keep gas manageable, but wide enough to trigger the bug (≥2 wins).
        plays = bound(plays, 1, 10);
        uint256 initialBankBalance = address(c.bank()).balance;
        uint256 totalFees = 0;

        // Simulate a sequence of plays; each play costs exactly TICKET_AMOUNT = 10 wei.
        for (uint256 i = 0; i < plays; i++) {
            address player = address(uint160(1000 + i)); // deterministic, unique addresses
            vm.deal(player, 10);
            vm.prank(player);
            // We catch the outcome to account for fees only when a win occurs.
            try c.play{value: 10}() {
                // A win occurred: fee of 1 was transferred to bank, so track it.
                totalFees += 1;
            } catch {
                // Loss: no fee transferred, pot accumulates, nothing to track.
            }
        }

        // Invariant: pot must equal contract balance plus total fees sent to bank.
        uint256 contractBalance = address(c).balance;
        uint256 pot = c.pot();
        uint256 expectedPot = contractBalance + totalFees;
        assertTrue(pot == expectedPot);
    }
}

